const L=h=>{const c=i=>{let v=parseInt(h.slice(i,i+2),16)/255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4};return 0.2126*c(1)+0.7152*c(3)+0.0722*c(5)};
const R=(a,b)=>{const [x,y]=[L(a),L(b)].sort((p,q)=>q-p);return ((x+0.05)/(y+0.05)).toFixed(2)};
for (const fg of ["#000000","#241a05","#1b1e2b"]) console.log(fg, R(fg,"#e5484d"));
console.log("ring light on card", R("#b06a0c","#ffffff"), "sidebar ring", R("#d8891a","#1e2233"), "accent sidebar", R("#f5b843","#10121c"));'

